mapper.select:
SELECT a.*, b.product_name, b.product_code, b.status AS product_status, b.product_spec, b.unit, b.near_expiry_days, c.owner_code, c.owner_name, d.location_code, d.location_type, d.location_category, e.zone_name, e.zone_type, e.storage_type AS location_storage_type, f.warehouse_name, a.batch_number AS stock_batch_key, si.batch_number AS display_batch_number, si.id AS inbound_order_item_id, si.order_id AS inbound_order_id, sio.order_number AS inbound_order_number, sio.supplier_id AS supplier_id, fs.supplier_name AS supplier_name, si.production_date AS production_date, si.expiry_date AS source_expiry_date FROM wms_inventory a LEFT JOIN wms_products b ON a.product_id = b.id LEFT JOIN wms_cargo_owners c ON b.owner_id = c.id LEFT JOIN wms_storage_locations d ON a.location_code = d.location_code LEFT JOIN wms_storage_zones e ON d.zone_id = e.id LEFT JOIN wms_warehouses f ON f.id = e.warehouse_id LEFT JOIN wms_stock_in_order_items si ON a.batch_number LIKE 'FL:%' AND si.id = SUBSTRING(a.batch_number, 4) AND si.product_id = a.product_id LEFT JOIN wms_stock_in_orders sio ON sio.id = si.order_id LEFT JOIN fresh_supplier fs ON fs.id = sio.supplier_id WHERE 1 = 1
AND a.id = #{id}
AND b.product_name LIKE concat('%',#{productName},'%')
AND b.product_code = #{productCode}
AND c.owner_code = #{ownerCode}
AND c.owner_name LIKE concat('%',#{ownerName},'%')
AND f.warehouse_name LIKE concat('%',#{warehouseName},'%')
AND f.warehouse_code = #{warehouseCode}
AND e.zone_type = #{zoneType}
AND d.location_code = #{locationCode}
ORDER BY b.product_name, si.expiry_date, d.location_code, a.id
